/**
 * Generates the Swift side of Junco's tokens from packages/tokens/src/tokens.css, so iOS and the
 * web always share one source of truth.
 *
 *   node scripts/build-swift-tokens.ts           write the generated files
 *   node scripts/build-swift-tokens.ts --check   fail if they are out of date (CI)
 *
 * Writes:
 *   packages/swift/Sources/JuncoTokens/Tokens.generated.swift   plain Swift values (Linux-safe)
 *   packages/swift/Sources/JuncoUI/Palette.generated.swift      SwiftUI Color accessors
 */
import { readFileSync, writeFileSync } from "node:fs";
import { oklchToLinearRgb, parseOklch } from "../packages/tokens/src/color.ts";
import { controlPairs, MIN_CONTROL_CONTRAST, MIN_TEXT_CONTRAST, textPairs } from "../packages/tokens/src/pairs.ts";
import { parseTokens } from "../packages/tokens/src/parse.ts";

const root = new URL("..", import.meta.url).pathname;
const css = readFileSync(`${root}packages/tokens/src/tokens.css`, "utf8");
const { light, dark: darkOnly } = parseTokens(css);
const dark = { ...light, ...darkOnly };

const HEADER = `// Generated by scripts/build-swift-tokens.ts from packages/tokens/src/tokens.css.
// Do not edit by hand: change tokens.css and run \`pnpm swift:tokens\`.
`;

/** "primary-foreground" -> "primaryForeground", "chart-1" -> "chart1". */
const camel = (name: string) => name.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
const num = (n: number) => {
  const s = (Math.round(n * 10000) / 10000).toString();
  return s.includes(".") ? s : `${s}.0`;
};

/** oklch(...) -> gamma-encoded sRGB + alpha, each 0..1 (what UIColor/NSColor expect). */
function srgb(value: string): [number, number, number, number] | null {
  const c = parseOklch(value);
  if (!c) return null;
  const encode = (x: number) => (x <= 0.0031308 ? 12.92 * x : 1.055 * x ** (1 / 2.4) - 0.055);
  const [r, g, b] = oklchToLinearRgb(c).map(encode) as [number, number, number];
  return [r, g, b, c.alpha];
}
const rgba = (v: [number, number, number, number]) => `JuncoRGBA(red: ${num(v[0])}, green: ${num(v[1])}, blue: ${num(v[2])}, alpha: ${num(v[3])})`;

const remToPt = (v: string) => parseFloat(v) * 16;
const msToS = (v: string) => (v.endsWith("ms") ? parseFloat(v) / 1000 : parseFloat(v));

// Colors: every token whose light value is an oklch() color.
const colorNames = Object.keys(light).filter((k) => srgb(light[k]!) && !k.startsWith("shadow-"));

const lines: string[] = [HEADER, "// swiftlint:disable all", "", "public enum JuncoTokens {"];

lines.push("  /// Semantic colors, light and dark. Names match the CSS variables (`--primary-foreground` -> `primaryForeground`).");
lines.push("  public enum Colors {");
for (const name of colorNames) {
  lines.push(`    public static let ${camel(name)} = JuncoColorToken(name: "${name}", light: ${rgba(srgb(light[name]!)!)}, dark: ${rgba(srgb(dark[name]!)!)})`);
}
lines.push(`    public static let all: [JuncoColorToken] = [${colorNames.map(camel).join(", ")}]`);
lines.push("  }", "");

lines.push("  /// Text color on background pairs that must reach 4.5:1 contrast, and control parts that must reach 3:1.");
lines.push("  public enum ContrastPairs {");
lines.push(`    public static let minimumText: Double = ${num(MIN_TEXT_CONTRAST)}`);
lines.push(`    public static let minimumControl: Double = ${num(MIN_CONTROL_CONTRAST)}`);
lines.push(`    public static let text: [(String, String)] = [${textPairs.map(([a, b]) => `("${a}", "${b}")`).join(", ")}]`);
lines.push(`    public static let control: [(String, String)] = [${controlPairs.map(([a, b]) => `("${a}", "${b}")`).join(", ")}]`);
lines.push("  }", "");

lines.push("  /// The 4pt spacing scale. `Spacing.x(4)` is 16pt, like `p-4` on the web.");
lines.push("  public enum Spacing {");
lines.push(`    public static let unit: Double = ${num(remToPt(light["spacing"]!))}`);
lines.push("    public static func x(_ steps: Double) -> Double { steps * unit }");
lines.push("  }", "");

lines.push("  /// Corner radii in points.");
lines.push("  public enum Radius {");
lines.push(`    /// Cards and inputs.\n    public static let card: Double = ${num(remToPt(light["radius"]!))}`);
lines.push(`    /// Small controls.\n    public static let control: Double = ${num(remToPt(light["radius-sm"]!))}`);
lines.push(`    public static let xs: Double = ${num(remToPt(light["radius-xs"]!))}`);
lines.push(`    /// Tags and pills.\n    public static let pill: Double = 9999.0`);
lines.push("  }", "");

const sizes = Object.keys(light).filter((k) => /^text-[a-z0-9]+$/.test(k));
lines.push("  /// The type scale in points, with line heights.");
lines.push("  public enum FontSize {");
for (const k of sizes) {
  const size = remToPt(light[k]!);
  const lh = light[`${k}--line-height`]!;
  const lineHeight = lh.endsWith("rem") ? remToPt(lh) : parseFloat(lh) * size;
  lines.push(`    public static let ${camel(k.slice(5).replace(/^(\d)xl$/, "xl$1"))} = JuncoFontSize(size: ${num(size)}, lineHeight: ${num(lineHeight)})`);
}
lines.push("  }", "");

lines.push("  /// Font weights (CSS numeric weights).");
lines.push("  public enum FontWeight {");
for (const k of Object.keys(light).filter((k) => k.startsWith("font-weight-"))) {
  lines.push(`    public static let ${camel(k.slice(12))}: Int = ${parseInt(light[k]!, 10)}`);
}
lines.push("  }", "");

lines.push("  /// Durations in seconds. Multiply by the motion scale (see JuncoMotion) before animating.");
lines.push("  public enum Duration {");
for (const k of ["duration-fast", "duration-base", "duration-slow"]) lines.push(`    public static let ${k.slice(9)}: Double = ${num(msToS(light[k]!))}`);
lines.push(`    public static let stagger: Double = ${num(msToS(light["stagger"]!))}`);
lines.push("  }", "");

lines.push("  /// Easing curves as cubic-bezier control points.");
lines.push("  public enum Easing {");
for (const k of Object.keys(light).filter((k) => k.startsWith("ease-"))) {
  const [x1, y1, x2, y2] = /cubic-bezier\(([^)]+)\)/.exec(light[k]!)![1]!.split(",").map((v) => parseFloat(v));
  lines.push(`    public static let ${camel(k.slice(5))} = JuncoCubicBezier(x1: ${num(x1!)}, y1: ${num(y1!)}, x2: ${num(x2!)}, y2: ${num(y2!)})`);
}
lines.push("  }", "");

lines.push("  /// The motion switch: full, subtle (0.6) or off (0). Mirrors data-motion on the web.");
lines.push("  public enum MotionScale {");
lines.push("    public static let full: Double = 1.0");
lines.push(`    public static let subtle: Double = ${num(parseFloat(/\[data-motion="subtle"\]\s*\{\s*--motion-scale:\s*([\d.]+)/.exec(css)![1]!))}`);
lines.push("    public static let off: Double = 0.0");
lines.push("  }");
lines.push("}");

const tokensSwift = lines.join("\n") + "\n";

// SwiftUI accessors: Color.junco.primary etc.
const palette = [
  HEADER,
  "#if canImport(SwiftUI)",
  "import SwiftUI",
  "import JuncoTokens",
  "",
  "/// Every Junco color as a SwiftUI `Color` that switches with light and dark mode: `Color.junco.primary`.",
  "public struct JuncoPalette: Sendable {",
  ...colorNames.map((n) => `  public var ${camel(n)}: Color { Color(junco: JuncoTokens.Colors.${camel(n)}) }`),
  "}",
  "",
  "public extension Color {",
  "  /// Junco's semantic colors. `Text(\"Hi\").foregroundStyle(Color.junco.mutedForeground)`.",
  "  static let junco = JuncoPalette()",
  "}",
  "#endif",
  "",
].join("\n");

const outputs: Array<[string, string]> = [
  [`${root}packages/swift/Sources/JuncoTokens/Tokens.generated.swift`, tokensSwift],
  [`${root}packages/swift/Sources/JuncoUI/Palette.generated.swift`, palette],
];

if (process.argv.includes("--check")) {
  const stale = outputs.filter(([path, content]) => {
    try {
      return readFileSync(path, "utf8") !== content;
    } catch {
      return true;
    }
  });
  if (stale.length) {
    console.error(`Swift tokens are out of date: ${stale.map(([p]) => p.replace(root, "")).join(", ")}\nRun: pnpm swift:tokens`);
    process.exit(1);
  }
  console.log("swift tokens: up to date");
} else {
  for (const [path, content] of outputs) writeFileSync(path, content);
  console.log(`swift tokens: ${colorNames.length} colors, ${sizes.length} type sizes -> packages/swift`);
}
